    "content": "var assert = require('assert');\nvar ms = require('./');\n\ndescribe('proof', function () {\n  it('parses the documented \"yr\" unit', function () {\n    // ms 2.1.3 documents 'yr' as a valid year unit and the switch still\n    // handles case 'yr', but the diff dropped `yrs?` -> `yrs` from the parse\n    // regex, so '1yr' no longer matches and returns undefined.\n    var year = 365.25 * 24 * 60 * 60 * 1000;\n    assert.strictEqual(ms('1yr'), year);\n    assert.strictEqual(ms('2yr'), 2 * year);\n  });\n});\n"
  },
  "note": "The diff changes `yrs?` to `yrs` in the parse regex, so the unit `yr` — supported in 2.1.3 and still listed in the switch statement — no longer matches. `ms('1yr')` now returns undefined instead of 31557600000."
}
```

